/** Injected by vite.config.ts: the configured model id, or '' when no LLM is set up (the app then uses the demo provider). */
declare const __LLM_MODEL__: string
/** Injected by vite.config.ts: optional JSON object of extra request-body fields for the LLM API, or ''. */
declare const __LLM_EXTRA_BODY__: string
